// Builds the before/after recommendation and a study verdict from study results (server-side).
// Percentages come from the study data; nothing is generated by an LLM.
import { getFlashpointAdapter } from "./flashpoint";
import { getDecision } from "./data";
import { topOption } from "./metrics";
import type { Decision, StudyResults, StudyVerdict } from "./types";

/** What each answer option means as a store action. Unknown options fall back to a generic action. */
const ACTIONS: Record<string, string> = {
  "Extra cheese": "Offer free extra cheese at lunch",
  "$1 off": "Run a $1-off lunch promo",
  "Faster line": "Add a second register and a pre-order lane at lunch",
};
export const actionFor = (option: string) => ACTIONS[option] ?? `Act on "${option}"`;

const pct = (r: StudyResults, key: "synthetic" | "real", option: string) => r[key][r.options.indexOf(option)];

/** How strongly the real answers point to one option (code rule on winner share and margin). */
export function studyVerdict(r: StudyResults): StudyVerdict {
  const realTop = topOption(r, "real");
  const syntheticTop = topOption(r, "synthetic");
  const sorted = [...r.real].sort((a, b) => b - a);
  const share = sorted[0] ?? 0;
  const margin = share - (sorted[1] ?? 0);
  const strength = share >= 50 && margin >= 20 ? "Strongly supported" : margin >= 10 ? "Plausible" : "Insufficient info";
  return { strength, predictionHeld: realTop === syntheticTop, realTop, syntheticTop };
}

const addDays = (days: number) => {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
};

export function buildDecision(r: StudyResults, storeId: string): { decision: Decision; studyVerdict: StudyVerdict } {
  const v = studyVerdict(r);
  const base = getDecision(storeId); // owner / metric / review date come from the saved data
  const decision: Decision = {
    before: {
      title: actionFor(v.syntheticTop),
      why: `Synthetic customers predicted "${v.syntheticTop}" (${pct(r, "synthetic", v.syntheticTop)}%).`,
    },
    after: {
      title: actionFor(v.realTop),
      why: `Real people said "${v.realTop}" (${pct(r, "real", v.realTop)}%); synthetic customers gave it ${pct(r, "synthetic", v.realTop)}%.`,
    },
    owner: base?.owner ?? "Store general manager",
    metric: base?.metric ?? "Weekday lunch sales back within 3% of the prior 6-week average",
    reviewDate: base?.reviewDate ?? addDays(14),
  };
  return { decision, studyVerdict: v };
}

/** Used by the API route and the decision page. Returns null if there is no study for the store. */
export async function getDecisionForStore(storeId: string) {
  const adapter = getFlashpointAdapter();
  const results = await adapter.getStudyResults(storeId);
  if (!results) return null;
  return { mode: adapter.mode, ...buildDecision(results, storeId) };
}
